<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
$canAttendance=has_permission('attendance.manage');$canPayroll=has_permission('payroll.manage');
if(!$canAttendance&&!$canPayroll&&!has_permission('employees.manage')){http_response_code(403);exit('Human Resources access is not assigned to your account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='attendance'){
  require_permission('attendance.manage');$user=filter_var($_POST['user_id']??'',FILTER_VALIDATE_INT);$date=trim((string)($_POST['work_date']??''));$status=(string)($_POST['status']??'');$in=trim((string)($_POST['clock_in']??''));$out=trim((string)($_POST['clock_out']??''));$note=trim((string)($_POST['note']??''));$parsed=DateTime::createFromFormat('!Y-m-d',$date);$timePattern='/^(?:[01]\d|2[0-3]):[0-5]\d$/';
  $staffCheck=$pdo->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=:id AND r.role_key<>'patient_portal'");$staffCheck->execute(['id'=>$user]);
  if(!$user||!$staffCheck->fetch()||!$parsed||$parsed->format('Y-m-d')!==$date||$parsed>new DateTime('today')||!in_array($status,['present','absent','leave'],true)||($in!==''&&!preg_match($timePattern,$in))||($out!==''&&!preg_match($timePattern,$out))||strlen($note)>500){set_flash('danger','Check the staff member, date, status, times, and note.');redirect('/hospital%20management/hr/index.php');}
  $q=$pdo->prepare("INSERT INTO staff_attendance(user_id,work_date,status,clock_in,clock_out,note,recorded_by) VALUES(:user,:date,:status,:clock_in,:clock_out,:note,:recorder) ON DUPLICATE KEY UPDATE status=VALUES(status),clock_in=VALUES(clock_in),clock_out=VALUES(clock_out),note=VALUES(note),recorded_by=VALUES(recorded_by)");$q->execute(['user'=>$user,'date'=>$date,'status'=>$status,'clock_in'=>$in?:null,'clock_out'=>$out?:null,'note'=>$note?:null,'recorder'=>current_user()['id']]);record_audit('record','staff_attendance',(string)$user,'Attendance recorded for '.$date);set_flash('success','Attendance record saved.');
 }elseif($action==='payroll'){
  require_permission('payroll.manage');$user=filter_var($_POST['user_id']??'',FILTER_VALIDATE_INT);$periodInput=trim((string)($_POST['pay_period']??''));$period=preg_match('/^\d{4}-\d{2}$/',$periodInput)?$periodInput.'-01':'';$gross=trim((string)($_POST['gross_amount']??''));$deductions=trim((string)($_POST['deductions']??'0'));$month=DateTime::createFromFormat('!Y-m-d',$period);$validAmount=static fn(string $v):bool=>preg_match('/^\d{1,10}(?:\.\d{1,2})?$/',$v)===1;
  $staffCheck=$pdo->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=:id AND r.role_key<>'patient_portal'");$staffCheck->execute(['id'=>$user]);
  if(!$user||!$staffCheck->fetch()||!$month||$month->format('Y-m-d')!==$period||$month->format('d')!=='01'||!$validAmount($gross)||!$validAmount($deductions)||(float)$gross<=0||(float)$deductions>(float)$gross){set_flash('danger','Choose an employee, first day of a pay month, and valid gross and deduction amounts.');redirect('/hospital%20management/hr/index.php');}
  $existing=$pdo->prepare('SELECT status FROM payroll_entries WHERE user_id=:user AND pay_period=:period');$existing->execute(['user'=>$user,'period'=>$period]);if($existing->fetchColumn()==='paid'){set_flash('danger','A paid payroll entry cannot be changed.');redirect('/hospital%20management/hr/index.php');}$net=number_format((float)$gross-(float)$deductions,2,'.','');$q=$pdo->prepare("INSERT INTO payroll_entries(user_id,pay_period,gross_amount,deductions,net_amount,status,recorded_by) VALUES(:user,:period,:gross,:deductions,:net,'prepared',:recorder) ON DUPLICATE KEY UPDATE gross_amount=VALUES(gross_amount),deductions=VALUES(deductions),net_amount=VALUES(net_amount),recorded_by=VALUES(recorded_by)");$q->execute(['user'=>$user,'period'=>$period,'gross'=>$gross,'deductions'=>$deductions,'net'=>$net,'recorder'=>current_user()['id']]);record_audit('prepare','payroll',(string)$user,'Payroll prepared for '.$period);set_flash('success','Payroll entry saved.');
 }elseif($action==='paid'){
  require_permission('payroll.manage');$id=filter_var($_POST['payroll_id']??'',FILTER_VALIDATE_INT);$q=$pdo->prepare("UPDATE payroll_entries SET status='paid' WHERE id=:id AND status='prepared'");$q->execute(['id'=>$id]);if($q->rowCount()){record_audit('pay','payroll',(string)$id,'Payroll marked paid');set_flash('success','Payroll marked as paid.');}else set_flash('warning','Payroll entry not found or already paid.');
 }else{http_response_code(400);exit('Unknown HR action.');}redirect('/hospital%20management/hr/index.php');
}
$staff=$pdo->query("SELECT u.id,u.full_name,r.name AS role_name,u.payment_method,u.payment_details FROM users u JOIN roles r ON r.id=u.role_id WHERE u.is_active=1 AND r.role_key<>'patient_portal' ORDER BY u.full_name")->fetchAll();
$attendance=$canAttendance?$pdo->query('SELECT a.id,a.work_date,a.status,a.clock_in,a.clock_out,a.note,u.full_name FROM staff_attendance a JOIN users u ON u.id=a.user_id ORDER BY a.work_date DESC,u.full_name LIMIT 300')->fetchAll():[];
$payroll=$canPayroll?$pdo->query('SELECT p.id,p.pay_period,p.gross_amount,p.deductions,p.net_amount,p.status,u.full_name,u.payment_method,u.payment_details FROM payroll_entries p JOIN users u ON u.id=p.user_id ORDER BY p.pay_period DESC,u.full_name LIMIT 300')->fetchAll():[];
$pageTitle='Human Resources';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Human Resources</h2><p>Record staff attendance and leave, and prepare monthly payroll entries.</p></div></div>
<?php if($canAttendance):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Attendance and leave</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="attendance"><div class="col-md-3"><label class="form-label">Employee</label><select class="form-select" name="user_id" required><option value="">Select staff member</option><?php foreach($staff as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['full_name'].' · '.$s['role_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Date</label><input class="form-control" type="date" name="work_date" max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status"><option value="present">Present</option><option value="absent">Absent</option><option value="leave">Leave</option></select></div><div class="col-md-2"><label class="form-label">Clock in</label><input class="form-control" type="time" name="clock_in"></div><div class="col-md-2"><label class="form-label">Clock out</label><input class="form-control" type="time" name="clock_out"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Save</button></div><div class="col-12"><label class="form-label">Note</label><input class="form-control" name="note" maxlength="500"></div></form></section><section class="content-card"><div class="card-heading"><h3>Attendance register</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Staff member</th><th>Status</th><th>Hours</th><th>Note</th></tr></thead><tbody><?php if(!$attendance):?><tr><td colspan="5" class="empty-state">No attendance records.</td></tr><?php else:foreach($attendance as $a):?><tr><td><?=e(date('M j, Y',strtotime($a['work_date'])))?></td><td><?=e($a['full_name'])?></td><td><?=e(ucfirst($a['status']))?></td><td><?=e(($a['clock_in']?substr($a['clock_in'],0,5):'—').' – '.($a['clock_out']?substr($a['clock_out'],0,5):'—'))?></td><td><?=e($a['note']?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<?php if($canPayroll):?><section class="content-card form-card"><div class="card-heading"><h3>Prepare payroll</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="payroll"><div class="col-md-4"><label class="form-label">Employee</label><select class="form-select" name="user_id" id="payroll-user" required><option value="">Select staff member</option><?php foreach($staff as $s):?><option value="<?=(int)$s['id']?>" data-pm="<?=e($s['payment_method']??'')?>" data-pd="<?=e($s['payment_details']??'')?>"><?=e($s['full_name'].' · '.$s['role_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Payment method</label><input class="form-control" id="payroll-pm" readonly placeholder="—"></div><div class="col-md-2"><label class="form-label">Pay month</label><input class="form-control" type="month" name="pay_period" required></div><div class="col-md-2"><label class="form-label">Gross amount</label><input class="form-control" type="number" min="0.01" step="0.01" name="gross_amount" required></div><div class="col-md-2"><label class="form-label">Deductions</label><input class="form-control" type="number" min="0" step="0.01" name="deductions" value="0" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary">Save payroll</button></div></form><script>document.getElementById('payroll-user').addEventListener('change',function(){var o=this.options[this.selectedIndex];var pm=o.dataset.pm||'';var pd=o.dataset.pd||'';document.getElementById('payroll-pm').value=pm?(pm.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()))+(pd?' – '+pd:''):'';});</script><div class="form-text mt-2">Payroll values are available only to accounts with payroll permission. Tax calculations and payslip exports are not included.</div></section><section class="content-card"><div class="card-heading"><h3>Payroll register</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Pay month</th><th>Staff member</th><th>Payment method</th><th>Gross</th><th>Deductions</th><th>Net</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$payroll):?><tr><td colspan="8" class="empty-state">No payroll entries.</td></tr><?php else:foreach($payroll as $p):?><tr><td><?=e(date('M Y',strtotime($p['pay_period'])))?></td><td><?=e($p['full_name'])?></td><td><?php $pm=$p['payment_method']??'';echo $pm?e(ucwords(str_replace('_',' ',$pm))).($p['payment_details']?' <small class="text-muted">'.e($p['payment_details']).'</small>':''):'<span class="text-muted">—</span>';?></td><td><?=number_format((float)$p['gross_amount'],2)?></td><td><?=number_format((float)$p['deductions'],2)?></td><td><?=number_format((float)$p['net_amount'],2)?></td><td><?=e(ucfirst($p['status']))?></td><td><?php if($p['status']==='prepared'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="paid"><input type="hidden" name="payroll_id" value="<?=(int)$p['id']?>"><button class="btn btn-sm btn-outline-secondary">Mark paid</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
